 label(.06,.15,'PCA   3D → 2D ?',26);label(.06,.31,'Y = XP',26);label(.07,.42,'center X first',15);label(.51,.82,'what is lost?',20);line([[.57,.2],[.57,.66],[.9,.66]]);line([[.57,.66],[.42,.82]]);line([[.49,.66],[.83,.3]],'#d59a69');[[.58,.54],[.61,.45],[.7,.45],[.73,.32],[.78,.37]].forEach(([x,y])=>line([[x,y],[x+.004,y+.006]]));label(.08,.56,'projection ≠ just rotate',17);line([[.07,.6],[.43,.6]],'#d3a16d');label(.08,.81,'??  variance',21);
