let audio=new Audio('assets/pca-lecture.wav'),mode='demo',audioId='pca',audioURL=null,audioBlob=null,audioName='PCA 合成课堂.wav',sessions=[],files=[],fileId=null,filePage=1,recording=false,recorder=null,micStream=null,recordStart=0,recordTimer,recordId=null,recordBusy=false;
