function updateSession(){const b=$('#recordButton');b.classList.toggle('recording',recording);b.disabled=recordBusy;b.innerHTML=recording?'<span class="record-dot"></span> 结束录音':'<span class="record-dot"></span> 开始录音';$('#sessionStatus').innerHTML=`<i class="status-dot"></i> ${recording?'正在录音 · 继续手写':mode==='demo'?'PCA 示例课堂':'我的音频课堂'}`;$('#sessionDetail').textContent=mode==='demo'?'英文合成音频 · 中文参考译文':'仅本机录音 · 未接入自动转写';$('#audioTitle').textContent=mode==='demo'?'PCA · 课堂示例':audioName;$('#audioCaption').textContent=mode==='demo'?'合成语音，非真实课堂':'本地音频 · 可下载';$('.audio-chapters').hidden=mode!=='demo';updateAudio();window.MagicNote?.onRecordingState(recording)}
async function switchAudio(src,id,name,blob=null){audio.pause();if(audioURL){URL.revokeObjectURL(audioURL);audioURL=null}audio.src=src;audioId=id;audioName=name;audioBlob=blob;mode=id==='pca'?'demo':'real';if(src.startsWith('blob:'))audioURL=src;updateSession();renderNotebook();renderSupport()}
async function play(){if(recording)return;try{audio.paused?await audio.play():audio.pause()}catch{notify('请先导入或录制音频，再点击播放。')}}
async function seekSource(index){if(recording){window.MagicNote?.showSourceWhileRecording(index);return}if(mode!=='demo')await switchAudio('assets/pca-lecture.wav','pca','PCA 合成课堂.wav');const t=lecture[index]?.time||0;audio.currentTime=t;setView('transcript');requestAnimationFrame(()=>$('#segment-'+index)?.scrollIntoView({block:'nearest',behavior:'smooth'}));updateAudio();notify(`已定位到 ${fmt(t)}，点击底部播放可回听。`)}
async function startMic(){if(recordBusy||recording)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('浏览器不支持录音，请用 Chrome / Edge 的 HTTPS 页面。');return}$('#recordDialog').close();recordBusy=true;updateSession();try{micStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});audio.pause();mode='real';audioId=recordId=uid();audioName='课堂录音 '+new Date().toLocaleString('zh-CN');audio.removeAttribute('src');audioBlob=null;let chunks=[];recorder=new MediaRecorder(micStream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType});micStream?.getTracks().forEach(t=>t.stop());const entry={id:recordId,name:audioName,blob,duration:(Date.now()-recordStart)/1000,created:Date.now()};sessions.push(entry);await switchAudio(URL.createObjectURL(blob),entry.id,entry.name,blob);try{if(db)await dbPut('sessions',entry)}catch{notify('录音尚未持久保存，请下载音频备份。')}renderSidebar();notify('录音已结束。手写笔画保留了记录时刻，可定位回听。')};recorder.start(500);recording=true;recordStart=Date.now();setView('notes');recordTimer=setInterval(updateAudio,500);notify('正在录音。手写笔画会标记当前录音时间。')}catch(e){micStream?.getTracks().forEach(t=>t.stop());notify(e.name==='NotAllowedError'?'未取得麦克风权限，可重新尝试或导入音频。':'录音失败：'+e.message)}finally{recordBusy=false;updateSession()}}
function stopMic(){if(recorder?.state==='recording'){recording=false;clearInterval(recordTimer);recorder.stop();updateSession()}}
async function importAudio(file){if(!file)return;if(recording){notify('请先结束当前录音。');return}const entry={id:uid(),name:file.name,blob:file,created:Date.now()};await switchAudio(URL.createObjectURL(file),entry.id,entry.name,file);sessions.push(entry);try{if(db)await dbPut('sessions',entry)}catch{notify('文件可播放，但未持久保存，请保留原始音频。')}$('#recordDialog').close();renderSidebar();notify('音频已导入，可以回听和手写。')}
