 const p=page();root.innerHTML=`${recording?'<div class="recording-strip"><i></i> 录音中 · 你的每一笔都会关联当前录音时刻</div>':''}<div class="page-meta"><span>DATA MINING / WEEK 10</span><span>${p.sample?'示例草图 · 可以继续手写':'我的笔记'}</span></div><h2 class="note-title">${esc(p.title)}</h2><p class="note-subtitle">先记你的思路。不用写完整，也不用写工整。</p><div class="paper ${expanded?'canvas-expanded':''}" id="paper"><div class="drawing-toolbar"><button class="tool ${tool==='pen'?'active':''}" data-tool="pen">✎ 手写</button><button class="tool ${tool==='lasso'?'active':''}" data-tool="lasso">⌁ 圈选</button><button class="tool ${tool==='eraser'?'active':''}" data-tool="eraser">◇ 橡皮</button><span class="toolbar-divider"></span><button class="tool color" data-color="#4f6844" style="background:#4f6844" aria-label="绿色画笔"></button><button class="tool color" data-color="#c68b59" style="background:#c68b59" aria-label="橙色画笔"></button><span class="toolbar-spacer"></span><button class="tool" data-act="undo" aria-label="撤销一笔">↶</button><button class="tool" data-act="expand" aria-label="放大或收起手写区">${expanded?'收起':'⛶'}</button></div><div class="draw-area"><canvas id="handCanvas" aria-label="可用手写笔、鼠标、触屏绘画和套索圈选的笔记区"></canvas><span class="canvas-empty">${p.sample?'示例手写草图 · 选择「圈选」，圈住你卡住的一点':'在这里画图、写公式，留下自己的想法'}</span></div><div class="selection-badge ${selected.length?'selected':''}" id="selectionBadge"></div><textarea class="inline-editor" id="ownText" aria-label="补充自己的文字笔记" placeholder="也可以记一句：我卡在这里，因为……">${esc(p.text)}</textarea></div><div class="note-origin"><i class="origin-dot"></i> 我的手写与想法始终保留 <span style="margin-left:auto">可撤销 · 自动保存</span></div><div id="acceptedCards">${cardsHTML(p.cards)}</div>${!p.cards.length?'<div class="continue-card"><span>↗</span><div><b>把空缺，留给下一步理解。</b><p>圈出不懂的草图或公式，再点右侧「围绕圈选补充」。你决定收下哪些内容。</p></div></div>':''}`;
