function loadBili(){clipLocal=false;$('#videoFrame').innerHTML=`<iframe title="Bilibili 原始 PCA 讲解视频" src="https://player.bilibili.com/player.html?bvid=BV1QS4y1e7y6&page=1&autoplay=0&t=${clipStart}" allow="fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;$('#clipHint').innerHTML=`外部播放器可能因平台限制无法加载；<a class="source-link" href="https://www.bilibili.com/video/BV1QS4y1e7y6/?t=${clipStart}" target="_blank" rel="noopener">在 B站打开原视频 ↗</a>。时间轴是独立的片段标记工具，不读取视频字幕。`}
