function eig3(matrix){const a=matrix.map(r=>r.slice()),V=[[1,0,0],[0,1,0],[0,0,1]];for(let iter=0;iter<40;iter++){let p=0,q=1;for(let i=0;i<3;i++)for(let j=i+1;j<3;j++)if(Math.abs(a[i][j])>Math.abs(a[p][q])){p=i;q=j}if(Math.abs(a[p][q])<1e-12)break;const angle=.5*Math.atan2(2*a[p][q],a[q][q]-a[p][p]),c=Math.cos(angle),s=Math.sin(angle);const J=[[1,0,0],[0,1,0],[0,0,1]];J[p][p]=J[q][q]=c;J[p][q]=s;J[q][p]=-s;const matmul=(x,y)=>x.map(row=>y[0].map((_,j)=>row.reduce((sum,val,k)=>sum+val*y[k][j],0)));const t=J[0].map((_,i)=>J.map(r=>r[i]));const next=matmul(matmul(t,a),J),nv=matmul(V,J);for(let i=0;i<3;i++)for(let j=0;j<3;j++){a[i][j]=next[i][j];V[i][j]=nv[i][j]}}
 return [0,1,2].map(i=>({value:a[i][i],vector:V.map(r=>r[i])})).sort((a,b)=>b.value-a.value)}
const eigen=eig3(cov),totalVariance=points.reduce((s,p)=>s+dot(p,p),0)/points.length;
