function basis(){let t=angle*Math.PI/180;const mix=(a,b)=>add(mul(a,Math.cos(t)),mul(b,Math.sin(t)));return dims===1?[mix(eigen[0].vector,eigen[1].vector)]:[eigen[0].vector,mix(eigen[1].vector,eigen[2].vector)]}
