function renderLabControls(){window.MagicNote?.onCameraState(!!handStream);if(lab==='earth'&&window.MagicNote)return window.MagicNote.renderEarthControls();const root=$('#labControls');$$('[data-lab]').forEach(b=>b.classList.toggle('active',b.dataset.lab===lab));$('#labTitle').textContent=lab==='pca'?'转动视角，看见投影。':'两条路相交，就一定能转弯吗？';$('#sceneLegend').innerHTML=lab==='pca'?'<span><i style="background:#688f75"></i>原始点</span><span><i style="background:#cfa278"></i>投影点</span><span>虚线：丢失的分量</span>':'<span><i style="background:#8ca66e"></i>道路</span><span><i style="background:#d1a06e"></i>可达路线</span><span>教学示意，非真实地图</span>';
 root.innerHTML=lab==='pca'?`<div class="lab-control-card"><h3>保留几个坐标？</h3><div class="dimension-buttons"><button class="${dims===2?'active':''}" data-dims="2">3D → 2D</button><button class="${dims===1?'active':''}" data-dims="1">3D → 1D</button></div><label class="control-label" for="projectionAngle">改变投影方向 <span id="angleLabel">${angle}°</span></label><input id="projectionAngle" type="range" min="-90" max="90" value="${angle}"><button class="source-link" data-act="pca-best">回到 PCA 最优方向</button><label class="control-label" for="flattenAmount">原始点 → 投影点 <span id="flattenLabel">${Math.round(flatten*100)}%</span></label><input id="flattenAmount" type="range" min="0" max="100" value="${flatten*100}"><div class="lab-tip">先改变投影方向，再只拖动视角。观察：哪一种操作会改变保留方差？</div><p>只转动观察视角，保留的信息会改变吗？</p><button class="quiz-option" data-quiz="wrong">会，视角就是降维</button><button class="quiz-option" data-quiz="correct">不会，投影子空间才决定保留信息</button><p id="quizFeedback" class="fine-print"></p><button class="button light wide" data-act="save-lab">＋ 把这次观察记下来</button></div>`:`<div class="lab-control-card"><h3>利兹道路网络 · 概念示意</h3><p>地图上的交叉，可能是路口，也可能是一座桥。拓扑是否连通，会改变能走的路线。</p><div class="dimension-buttons"><button class="${bridge?'active':''}" data-bridge="true">跨线桥</button><button class="${!bridge?'active':''}" data-bridge="false">平面路口</button></div><div class="lab-tip">绿色为道路，橙色为 A→B 路线。切换桥与路口，再拖动视角观察交叉处。</div><p>这是道路连接关系的教学模型。真实城市数据需要另行接入，当前不提供导航。</p><button class="button light wide" data-act="save-lab">＋ 保存我的空间理解</button><button class="next-action" data-act="reset-view">回到初始视角 <span>↶</span></button></div>`;
 if(lab==='pca'){$('#projectionAngle').oninput=e=>{angle=+e.target.value;$('#angleLabel').textContent=angle+'°';drawScene()};$('#flattenAmount').oninput=e=>{flatten=+e.target.value/100;$('#flattenLabel').textContent=e.target.value+'%';drawScene()}}drawScene();}
function sceneProject(p,W,H){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),x=p[0]*cy-p[2]*sy,z=p[0]*sy+p[2]*cy,y=p[1]*cp-z*sp,depth=p[1]*sp+z*cp;const scale=Math.min(W*.21,H*.31)*(window.MagicNote?.zoom||1);return{x:W*.49+x*scale,y:H*.52-y*scale,z:depth}}
function drawScene(){const c=$('#sceneCanvas');if(!c||!$('#labDialog').open)return;const {ctx,w:W,h:H}=sizeCanvas(c);ctx.clearRect(0,0,W,H);const to=p=>sceneProject(p,W,H),line=(a,b,color,width=1,dashed=false)=>{a=to(a);b=to(b);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dashed?[4,4]:[]);ctx.stroke();ctx.setLineDash([])},label=(p,text,color='#9cb189')=>{p=to(p);ctx.fillStyle=color;ctx.font='11px Segoe UI';ctx.fillText(text,p.x+7,p.y-7)};
 if(lab==='earth'&&window.MagicNote){window.MagicNote.drawEarth(ctx,W,H);return}if(lab==='pca'){const bs=basis();if(dims===2){const corners=[[-1.9,-.95],[1.9,-.95],[1.9,.95],[-1.9,.95]].map(([a,b])=>to(add(mul(bs[0],a),mul(bs[1],b))));ctx.beginPath();corners.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle='#a7bf8740';ctx.fill();ctx.strokeStyle='#a8c28b';ctx.stroke()}bs.forEach((b,i)=>{line(mul(b,-2.05),mul(b,2.05),'#93b079',1.7);label(mul(b,2.05),'PC'+(i+1),'#8da574')});[[[2.2,0,0],'x₁'],[[0,1.7,0],'x₂'],[[0,0,1.8],'x₃']].forEach(([p,t])=>{line([0,0,0],p,'#bdccb0');label(p,t)});points.map(p=>({p,q:projection(p),z:to(p).z})).sort((a,b)=>a.z-b.z).forEach(({p,q})=>{line(p,q,'#cba58385',.8,true);const a=to(add(mul(p,1-flatten),mul(q,flatten))),b=to(q);ctx.beginPath();ctx.arc(b.x,b.y,3,0,Math.PI*2);ctx.strokeStyle='#cb9c70';ctx.lineWidth=1.2;ctx.stroke();ctx.beginPath();ctx.arc(a.x,a.y,3.8,0,Math.PI*2);ctx.fillStyle='#76977e';ctx.fill()});const s=pcaStats();$('#labMetrics').innerHTML=`<div class="metric"><small>新坐标维数</small><strong>${dims}D</strong><span>45 个中心化示例点</span></div><div class="metric"><small>保留方差</small><strong>${(s.retained*100).toFixed(1)}%</strong><span>由当前投影实时计算</span></div><div class="metric"><small>平均平方重建误差</small><strong>${s.error.toFixed(3)}</strong><span>和转动视角无关</span></div>`;
 }else{drawMap(ctx,to,line,label);}}
function drawMap(ctx,to,line,label){const A=[-1.8,0,0],B=[0,0,1.8],O=[0,0,0],E=[1.8,0,0],N=[0,0,-1.8];const bridgeH=bridge?.65:0;const horizontal=[A,[-.65,0,0],[0,bridgeH,0],[.65,0,0],E],vertical=[B,O,N],detour=[A,[-1.8,0,1.8],B];const road=(pts,color,width)=>pts.slice(1).forEach((p,i)=>line(pts[i],p,color,width));for(let i=-2;i<=2;i++)for(let j=-2;j<=2;j++){line([i,0,-2],[i,0,2],'#d3ddc8',.6);line([-2,0,j],[2,0,j],'#d3ddc8',.6)}road(detour,'#a8bd91',11);road(vertical,'#a8bd91',11);road(horizontal,'#789a73',12);road(bridge?detour:[A,O,B],'#d2a375',4);if(bridge){line([-.3,0,0],[-.3,.35,0],'#9fb58c',3);line([.3,0,0],[.3,.35,0],'#9fb58c',3);label([0,.85,0],'立交：无转向连接','#9ab285')}else{let c=to(O);ctx.beginPath();ctx.arc(c.x,c.y,7,0,Math.PI*2);ctx.fillStyle='#d1a376';ctx.fill();label(O,'可转向路口','#9aad86')}[A,B].forEach((p,i)=>{let q=to(p);ctx.beginPath();ctx.arc(q.x,q.y,6,0,Math.PI*2);ctx.fillStyle='#517e67';ctx.fill();label(p,i?'B · 教室':'A · 出发点','#6f8f64')});$('#labMetrics').innerHTML=`<div class="metric"><small>图上交叉点</small><strong>1</strong><span>二维位置一样</span></div><div class="metric"><small>交叉处可转向</small><strong>${bridge?'否':'是'}</strong><span>连接关系不同</span></div><div class="metric"><small>A → B 路线</small><strong>${bridge?'绕行':'直达路口'}</strong><span>示意图，不代表真实道路</span></div>`}
