// Camera frames and landmarks stay in this browser. Model inference runs in a worker.
let handWorker,handStream,handBusy=false,handReady=false,handRAF=0,handToken=0,handTimer,frameBusy=false,lastFrame=0,lastFinger=null;
function stopHands(){handToken++;cancelAnimationFrame(handRAF);clearTimeout(handTimer);handStream?.getTracks().forEach(t=>t.stop());handStream=null;handWorker?.terminate();handWorker=null;handReady=false;handBusy=false;frameBusy=false;lastFinger=null;$('#handVideo').srcObject=null;$('#cameraPreview').hidden=true;$('#cameraButton').textContent='◎ 开启手势控制';$('#cameraStatus').textContent='可选 · 鼠标和触屏也能操作';window.MagicNote?.onCameraState(false);}
async function startHands(){if(handStream||handBusy){stopHands();return}if(!navigator.mediaDevices?.getUserMedia){notify('浏览器不支持摄像头；可直接拖动三维图形。');return}handBusy=true;const token=++handToken;$('#cameraButton').textContent='停止加载';$('#cameraStatus').textContent='等待摄像头授权与本地模型加载…';handTimer=setTimeout(()=>{if(token===handToken){stopHands();notify('手势模型加载超时，可用鼠标或触屏继续操作。')}},45000);try{const stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false});if(token!==handToken){stream.getTracks().forEach(t=>t.stop());return}handStream=stream;$('#handVideo').srcObject=stream;await $('#handVideo').play();if(token!==handToken)return;$('#cameraPreview').hidden=false;window.MagicNote?.onCameraState(true);handWorker=new Worker('hands-worker.js');handWorker.onmessage=e=>{if(token!==handToken)return;if(e.data.type==='ready'){clearTimeout(handTimer);handReady=true;handBusy=false;$('#cameraButton').textContent='◎ 关闭手势控制';$('#cameraStatus').textContent='食指与拇指捏合移动：转动视角；松开暂停。';window.MagicNote?.onCameraState(true);handLoop(token)}else if(e.data.type==='result'){frameBusy=false;handleLandmarks(e.data.landmarks)}else if(e.data.type==='error'){console.warn('Hand tracking:',e.data.message);stopHands();notify('手势模型未能运行，鼠标和触屏仍可操作。')}};handWorker.onerror=()=>{stopHands();notify('手势组件加载失败，可用鼠标和触屏继续。')};handWorker.postMessage({type:'init',base:new URL('vendor/hands/',location.href).href})}catch(e){stopHands();notify(e.name==='NotAllowedError'?'摄像头权限未开启，可继续用鼠标和触屏。':'无法开启摄像头：'+e.message)}}
function handLoop(token){if(token!==handToken||!handReady)return;const now=performance.now();if(!frameBusy&&now-lastFrame>85&&$('#handVideo').readyState>=2){frameBusy=true;lastFrame=now;createImageBitmap($('#handVideo')).then(bitmap=>{if(token!==handToken){bitmap.close();return}handWorker.postMessage({type:'frame',bitmap,time:now},[bitmap])}).catch(()=>frameBusy=false)}handRAF=requestAnimationFrame(()=>handLoop(token))}
function handleLandmarks(hands){const c=$('#handOverlay');c.width=320;c.height=240;const ctx=c.getContext('2d'),p=hands?.[0],arHandled=window.MagicNote?.onHandFrame(hands);if(!p){lastFinger=null;if(!arHandled)$('#cameraStatus').textContent='把一只手放进镜头，食指与拇指捏合移动。';return}const links=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];ctx.strokeStyle='#b5dfa2';ctx.lineWidth=2;links.forEach(([a,b])=>{ctx.beginPath();ctx.moveTo(p[a].x*320,p[a].y*240);ctx.lineTo(p[b].x*320,p[b].y*240);ctx.stroke()});p.forEach(v=>{ctx.beginPath();ctx.arc(v.x*320,v.y*240,2,0,Math.PI*2);ctx.fillStyle='#e7f5d7';ctx.fill()});const pinch=Math.hypot(p[8].x-p[4].x,p[8].y-p[4].y)<.075;const f={x:1-p[8].x,y:p[8].y};if(!arHandled&&pinch&&lastFinger){yaw=clamp(yaw+(f.x-lastFinger.x)*4,-20,20);pitch=clamp(pitch+(f.y-lastFinger.y)*3,-1.4,1.4);drawScene()}lastFinger=pinch?f:null;if(!arHandled)$('#cameraStatus').textContent=pinch?'捏合中 · 移动食指转动视角':'已识别手部 · 捏合食指与拇指开始控制';}

